import React, { useState, useEffect, useRef } from 'react';
import io from 'socket.io-client';
import './Chat.css';

const Chat = ({ username, onLogout }) => {
  const [socket, setSocket] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [users, setUsers] = useState([]);
  const [typingUsers, setTypingUsers] = useState(new Map());
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);
  const typingTimeoutRef = useRef(null);
  const [selectedUser, setSelectedUser] = useState(null);

  useEffect(() => {
    // 1. Only create the socket connection once per username
    const newSocket = io('http://localhost:5000');
    setSocket(newSocket);

    if (username && window._password) {
      newSocket.emit('login', { username, password: window._password });
    }

    // Listen for chat history
    newSocket.on('chatHistory', (history) => {
      setMessages(history);
    });

    // Listen for new messages
    newSocket.on('message', (message) => {
      setMessages(prev => [...prev, message]);
    });

    // Listen for user list updates
    newSocket.on('userList', (userList) => {
      setUsers(userList.filter(u => u.username !== username));
    });

    // Listen for typing indicators
    newSocket.on('userTyping', (data) => {
      setTypingUsers(prev => {
        const newMap = new Map(prev);
        if (data.isTyping) {
          newMap.set(data.socketId, data.username || 'Someone');
        } else {
          newMap.delete(data.socketId);
        }
        return newMap;
      });
    });

    // Listen for private messages
    newSocket.on('privateMessages', (msgs) => {
      setMessages(msgs);
    });

    // Listen for new messages (real-time)
    newSocket.on('message', (message) => {
      if (
        message.type === 'user' &&
        ((message.sender === username && message.recipient === selectedUser?.username) ||
         (message.sender === selectedUser?.username && message.recipient === username))
      ) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => {
      newSocket.close();
    };
  }, [username]);

  // 2. Fetch all users only once per username
  useEffect(() => {
    fetch('http://localhost:5000/all-users')
      .then(res => res.json())
      .then(data => setUsers(data.filter(u => u.username !== username)))
      .catch(err => console.error('Failed to fetch users:', err));
  }, [username]);

  // 3. Fetch private messages when selectedUser changes
  useEffect(() => {
    if (socket && selectedUser) {
      socket.emit('getPrivateMessages', { withUser: selectedUser.username });
    }
  }, [socket, selectedUser]);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (newMessage.trim() && socket && selectedUser) {
      socket.emit('sendMessage', { content: newMessage.trim(), recipient: selectedUser.username });
      setNewMessage('');
      setIsTyping(false);
      socket.emit('typing', false);
    }
  };

  const handleTyping = (e) => {
    setNewMessage(e.target.value);
    
    if (!isTyping) {
      setIsTyping(true);
      socket?.emit('typing', true);
    }

    // Clear existing timeout
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }

    // Set new timeout to stop typing indicator
    typingTimeoutRef.current = setTimeout(() => {
      setIsTyping(false);
      socket?.emit('typing', false);
    }, 1000);
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString([], { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  };

  const getTypingIndicator = () => {
    const typingCount = typingUsers.size;
    if (typingCount === 0) return null;
    const typingNames = Array.from(typingUsers.values());
    if (typingCount === 1) {
      return <div className="typing-indicator">{typingNames[0]} is typing...</div>;
    } else {
      return <div className="typing-indicator">{typingNames.join(', ')} are typing...</div>;
    }
  };

  return (
    <div className="chat-container">
      {/* Header */}
      <div className="chat-header">
        <div className="header-info">
          <h2>ChatApp</h2>
          <p>Welcome, {username}!</p>
        </div>
        <div className="header-actions">
          <span className="online-status">
            <span className="status-dot"></span>
            {users.length} online
          </span>
          <button onClick={onLogout} className="logout-button">
            Logout
          </button>
        </div>
      </div>

      <div className="chat-main">
        {/* Users Sidebar */}
        <div className="users-sidebar">
          <h3>All Users ({users.length})</h3>
          <div className="users-list">
            {users.map(user => (
              <div key={user.username} className={`user-item${selectedUser?.username === user.username ? ' selected' : ''}`} onClick={() => setSelectedUser(user)}>
                <span className="user-avatar">
                  {user.username.charAt(0).toUpperCase()}
                </span>
                <span className="user-name">{user.username}</span>
                <span className={`online-indicator${user.isOnline ? ' online' : ' offline'}`}></span>
              </div>
            ))}
          </div>
        </div>

        {/* Chat Area */}
        <div className="chat-area">
          {/* Messages */}
          <div className="messages-container">
            {selectedUser ? (
              messages.map((message, index) => (
                <div 
                  key={message._id || index} 
                  className={`message ${message.type === 'system' ? 'system-message' : (message.sender === username ? 'user-message self' : 'user-message')}`}
                >
                  {message.type === 'user' && (
                    <div className="message-header">
                      <span className="message-username">{message.sender}</span>
                      <span className="message-time">{formatTime(message.timestamp)}</span>
                    </div>
                  )}
                  <div className="message-content">
                    {message.content}
                  </div>
                </div>
              ))
            ) : (
              <div className="no-chat">Select a user to start chatting</div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Typing Indicator (per chat) */}
          {getTypingIndicator()}

          {/* Message Input */}
          <form onSubmit={handleSendMessage} className="message-input-container">
            <input
              type="text"
              value={newMessage}
              onChange={handleTyping}
              placeholder={selectedUser ? `Message ${selectedUser.username}...` : 'Select a user to chat'}
              className="message-input"
              disabled={!socket || !selectedUser}
            />
            <button 
              type="submit" 
              className="send-button"
              disabled={!newMessage.trim() || !socket || !selectedUser}
            >
              Send
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Chat;
